T_PROTO_OUTPUT_VALID_HELD: assert property (@(posedge clk)
      disable iff (!reset_n)
      (out_valid && !out_ready) |=> out_valid);

T_PROTO_OUTPUT_PAYLOAD_STABLE: assert property (@(posedge clk)
      disable iff (!reset_n)
      out_stall_q |-> $stable(out_pd));

T_PROTO_RAM_POP_ONLY_WITH_A_READY_CONSUMER: assert property (@(posedge clk)
      disable iff (!reset_n)
      rd_pop |-> out_ready);

T_BOUNDRSP_OUTPUT_DELIVERS_WITHIN_N: assert property (@(posedge clk)
      disable iff (!reset_n)
      (ctr_out <= N_OUT_WAIT));

T_BOUNDRSP_READ_POPS_WITHIN_N: assert property (@(posedge clk)
      disable iff (!reset_n)
      (ctr_rdpop <= N_POP_WAIT));

T_BOUNDRSP_WRITE_POPS_WITHIN_N: assert property (@(posedge clk)
      disable iff (!reset_n)
      (ctr_wrpop <= N_POP_WAIT));

T_DEADLOCK_GLOBAL_PROGRESS_WITHIN_N: assert property (@(posedge clk)
      disable iff (!reset_n)
      (ctr_stall <= N_STALL));

T_RESET_PIPES_EMPTY: assert property (@(posedge clk)
      disable iff (!reset_n)
      !post_reset |-> (!p1_skid && !p1_pipe && !p2_skid && !p2_pipe));

T_LIFECYCLE_MODE_STAYS_MERGE_INT8: assert property (@(posedge clk)
      disable iff (!reset_n)
      post_reset |-> (!m_contract && !m_split && m_byte));

T_LIFECYCLE_NO_COLUMN_LEAVES_BEFORE_ITS_BANK_IS_COMPLETE: assert property (@(posedge clk)
      disable iff (!reset_n)
      rd_pop |-> (wr_rows == 5'd0));

T_PROTO_AXI_WLAST_ON_LAST_BEAT: assert property (@(posedge clk)
        disable iff (reset)
        (w_acc && dut_axi_wlast) |-> mem_w_beat == BEATW'(BURST_BEATS - 1));

T_DATA_STORE_MERGE_APPLIES_MASK: assert property (@(posedge clk)
        disable iff (reset)
        (sm_v && rsp_v) |-> dut_l2_response_data[sm_base+:8] == sm_byte);

T_BOUNDRSP_HIT_ANSWERED_NEXT_CYCLE: assert property (@(posedge clk)
        disable iff (reset)
        (l2r_valid && l2r_hit && l2r_req_packet_type != L2REQ_FLUSH) |=> rsp_v);

T_CONSERVE_ALL_SRC_CREDIT_ACCOUNT: assert property (@(posedge clk) disable iff (!rst_ok)
        (c_src1 == (5'd16 - e_t1_p_d)) && (c_src2 == (5'd16 - e_t2_p_d)) &&
        (c_src3 == (5'd16 - e_t5_p_d)));

T_BOUND_PATH_NIB_DEPTH: assert property (@(posedge clk) disable iff (!rst_ok)
        (e_t1_w <= 3'd4) && (e_t2_w <= 3'd4) &&
        (e_t5_n <= 3'd4) && (e_t8_n <= 3'd4));

T_BOUND_CREDIT_COUNTERS: assert property (@(posedge clk) disable iff (!rst_ok)
        (c_src0 <= 5'd16) && (c_src1 <= 5'd16) && (c_src2 <= 5'd16) &&
        (c_src3 <= 5'd16) && (sp_bad == 135'd0));

T_REQRSP_CREDIT_ONLY_ON_DEQUEUE: assert property (@(posedge clk) disable iff (!rst_ok)
        ((!crd[0]) || (e_t0_p != 0)) && ((!crd[1]) || (e_t1_p != 0)) &&
        ((!crd[2]) || (e_t2_p != 0)) && ((!crd[3]) || (e_t5_p != 0)));

T_PROTO_NO_SEND_WITHOUT_SPACE: assert property (@(posedge clk) disable iff (!rst_ok)
        ((!lv_t0e) || (e_t1_w <= 3'd3)) && ((!lv_t1e) || (e_t2_w <= 3'd3)) &&
        ((!lv_t2s) || (e_t5_n <= 3'd3)) && ((!lv_t5s) || (e_t8_n <= 3'd3)));

T_RESET_SOURCE_CREDIT_FULL: assert property (@(posedge clk) disable iff (!rst_ok)
        first_cycle |-> ((c_src0 == 5'd16) && (c_src1 == 5'd16) &&
                         (c_src2 == 5'd16) && (c_src3 == 5'd16)));

T_COHERENCE_NO_PERMISSION_AFTER_ACKED_INVALIDATE_T0: assert property (@(posedge clk) disable iff (!reset_n)
        (r_ev[0] && dut_pop_inv_t0) |=>
            (!sh_excl0[$past(r_key[0])] && !sh_shared0[$past(r_key[0])]));

T_PROTO_SPI_SRAM_WRITE_IN_INGRESS: assert property (@(posedge clk_i) disable iff (!rst_ni) (dut_mem_b_req && dut_mem_b_write) |->
      ((dut_mem_b_addr >= SramIngressIdx)
       && (dut_mem_b_addr < (SramIngressIdx + SramAw'(IngressWords)))));

T_RESET_CMDFIFO_EMPTY: assert property (@(posedge clk_i) disable iff (!rst_ni) $rose(rst_ni) |->
      (!dut_cmd_rvalid && (dut_cmd_wptr == 5'd0)
       && (dut_cmd_rptr == 5'd0)));
